import assert from 'node:assert/strict';
import type {Page} from 'playwright';
export async function verifyDashboardLayout(page:Page,origin:string,workspaceId:string,checkAccessibility:(page:Page,phase:string)=>Promise<void>){
 await page.setViewportSize({width:1280,height:900});await page.goto(origin+'/dashboard/app/workspaces/'+workspaceId+'/studio');
 await page.getByText('Edit pages and widget layout',{exact:true}).click();
 const editor=page.getByRole('region',{name:'Dashboard pages and layout',exact:true});
 await editor.getByLabel('Row for Revenue',{exact:true}).first().fill('20');await editor.getByLabel('Width for Revenue',{exact:true}).first().fill('6');await editor.getByLabel('Height for Revenue',{exact:true}).first().fill('4');await editor.getByRole('button',{name:'Apply layout for Revenue',exact:true}).first().click();
 await editor.getByText('Dashboard pages and layout saved.',{exact:true}).waitFor();await page.reload();await page.getByText('Edit pages and widget layout',{exact:true}).click();assert.equal(await editor.getByLabel('Row for Revenue',{exact:true}).first().inputValue(),'20');assert.equal(await editor.getByLabel('Width for Revenue',{exact:true}).first().inputValue(),'6');
 await editor.getByLabel('Page name',{exact:true}).fill('Details');await editor.getByRole('button',{name:'Add page',exact:true}).click();await editor.getByLabel('Page for Revenue',{exact:true}).first().selectOption({label:'Details'});
 await editor.getByLabel('Page name',{exact:true}).fill('Revenue focus');await editor.getByRole('button',{name:'Rename page',exact:true}).click();await editor.getByRole('button',{name:'Move page earlier',exact:true}).click();
 await editor.getByText('Dashboard pages and layout saved.',{exact:true}).waitFor();await page.reload();await page.getByText('Edit pages and widget layout',{exact:true}).click();await editor.getByLabel('Dashboard page',{exact:true}).selectOption({label:'Revenue focus'});
 const grid=page.getByRole('group',{name:'Dashboard widget grid',exact:true}),card=grid.getByRole('article').filter({has:page.getByRole('heading',{name:'Revenue',exact:true})});await card.waitFor();const point=await grid.evaluate(element=>{const s=getComputedStyle(element),gap=parseFloat(s.gap),rows=s.gridTemplateRows.split(' ').map(Number.parseFloat),pitch=(element.getBoundingClientRect().width+gap)/12;return {x:pitch*6.5+8,y:Array.from({length:6},(_,i)=>(rows[i]||40)+gap).reduce((a,b)=>a+b,0)+20+8};});
 await card.dragTo(grid,{sourcePosition:{x:8,y:8},targetPosition:point});await page.waitForFunction(()=>{const labels=[...document.querySelectorAll('label')];const label=labels.find(l=>l.textContent?.trim().startsWith('Row for Revenue'));return label?.querySelector('input')?.value==='7';});assert.equal(await editor.getByLabel('Column for Revenue',{exact:true}).first().inputValue(),'7');
 const resized=await grid.evaluate(element=>{const s=getComputedStyle(element),gap=parseFloat(s.gap),rows=s.gridTemplateRows.split(' ').map(Number.parseFloat),pitch=(element.getBoundingClientRect().width+gap)/12;return {x:pitch*8.5,y:rows.slice(0,8).reduce((sum,h)=>sum+h+gap,0)+(rows[8]||40)/2};});await grid.scrollIntoViewIfNeeded();const gridBounds=await grid.boundingBox(),handle=await card.getByRole('button',{name:'Resize Revenue',exact:true}).boundingBox();assert.ok(gridBounds&&handle);await page.mouse.move(handle.x+handle.width/2,handle.y+handle.height/2);await page.mouse.down();await page.mouse.move(gridBounds.x+resized.x,gridBounds.y+resized.y,{steps:8});await page.mouse.up();await page.waitForFunction(()=>{const labels=[...document.querySelectorAll('label')];return labels.find(l=>l.textContent?.trim().startsWith('Width for Revenue'))?.querySelector('input')?.value==='3';});
 assert.equal(await editor.getByLabel('Height for Revenue',{exact:true}).first().inputValue(),'3');await card.getByRole('button',{name:'Resize Revenue',exact:true}).click();assert.equal(await editor.getByLabel('Width for Revenue',{exact:true}).first().inputValue(),'3');assert.equal(await editor.getByLabel('Height for Revenue',{exact:true}).first().inputValue(),'3');await card.getByRole('button',{name:'Resize Revenue',exact:true}).press('Enter');assert.equal(await editor.getByLabel('Width for Revenue',{exact:true}).first().evaluate(input=>input===document.activeElement),true);await editor.getByText('Dashboard pages and layout saved.',{exact:true}).waitFor();await checkAccessibility(page,'dashboard-pages-layout');
 await page.setViewportSize({width:390,height:844});await checkAccessibility(page,'dashboard-pages-mobile');assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),'Dashboard page layout overflows mobile viewport');
 await page.setViewportSize({width:1280,height:900});page.once('dialog',dialog=>dialog.accept());await editor.getByRole('button',{name:'Delete page',exact:true}).click();await editor.getByText('Dashboard pages and layout saved.',{exact:true}).waitFor();await grid.getByRole('heading',{name:'Revenue',exact:true}).first().waitFor();
 console.log('PASS: saved widget positions/sizes, actual drag/resize, page create/rename/reorder/transfer/delete, desktop/mobile accessibility and retained metric cards.');
}
